def _pair(tid, ts, kind, payload, clears=None):
    """Vectorised 'pending' pairing per thread in the given (global) order: kind 0 = set pending (payload), kind 1 =
    consume it -> (tid, t_set, t_consume, payload). A later set overwrites, a consume clears; optional `clears` (bool,
    same length) are kind-0 records that only clear the pending entry (never pair)."""
    N = len(tid)
    if N == 0:
        return np.zeros(0, np.int32), np.zeros(0, np.int64), np.zeros(0, np.int64), np.zeros(0, np.int64)
    order = np.lexsort((np.arange(N), tid)); tid = tid[order]; ts = ts[order]; kind = kind[order]; payload = payload[order]
    clears = clears[order] if clears is not None else np.zeros(N, bool)
    pos = np.arange(N)
    # forward-filled position of the last kind-0 (set or clear) record, and of the last kind-1 record BEFORE each position
    last0 = np.maximum.accumulate(np.where(kind == 0, pos, -1))
    last1 = np.maximum.accumulate(np.where(kind == 1, pos, -1)); last1_excl = np.r_[-1, last1[:-1]]
    grp = np.r_[0, np.cumsum(np.diff(tid) != 0)]                      # thread group id per position
    ok = (kind == 1) & (last0 >= 0)
    ok &= grp[np.maximum(last0, 0)] == grp                              # the set belongs to the same thread
    ok &= last0 > last1_excl                                            # not consumed yet by an earlier consume
    ok &= ~clears[np.maximum(last0, 0)]                                 # and it is a real set, not a clear
    j = pos[ok]; i = last0[ok]
    return tid[j], ts[i], ts[j], payload[i]


def parse_kernel_parallel(session_dir, tz, workers=None):
    kdir = os.path.join(session_dir, 'kernel')
    if not os.path.isdir(kdir):
        sys.exit(f'no kernel trace in {kdir} (run with FISH_KERNEL_SCHED=1)')
    metas = glob.glob(os.path.join(kdir, '**', 'metadata'), recursive=True)
    if not metas:
        sys.exit(f'no CTF metadata under {kdir}')
