    streams = sorted(p for p in glob.glob(os.path.join(tdir, '*')) if os.path.isfile(p) and os.path.basename(p) != 'metadata')
    base = session_start_ts(session_dir, tz)
    midnight = base.replace(hour=0, minute=0, second=0, microsecond=0).timestamp(); base_tod = base.hour * 3600 + base.minute * 60 + base.second
    t = time.time(); tmp = tempfile.mkdtemp(prefix='fish_ksched_')
    jobs = [(s, metas[0], midnight, base_tod, os.path.join(tmp, f's{i}')) for i, s in enumerate(streams)]
    nproc = max(1, min(workers or len(jobs), len(jobs), os.cpu_count() or 1))
