    on = (ld('on_tid'), ld('on_t0'), ld('on_t1'))
    # off-CPU intervals from the merged switch records: pending[prev] = (ts, state) at the switch-out, consumed by the next
    # switch-in of that thread on any CPU. Global order = timestamp (ties: stream order, as babeltrace2 merges).
