    src = np.concatenate([np.full(len(np.load(f"{r['prefix']}_sw_ts.npy")), i, np.int16) for i, r in enumerate(res)]) if res else np.zeros(0, np.int16)
    o = np.lexsort((src, sw_ts)); sw_ts, sw_prev, sw_st, sw_next = sw_ts[o], sw_prev[o], sw_st[o], sw_next[o]
    M = len(sw_ts)
    rec_tid = np.empty(2 * M, np.int32); rec_ts = np.empty(2 * M, np.int64); rec_kind = np.empty(2 * M, np.int8); rec_pay = np.empty(2 * M, np.int64)
    rec_tid[0::2] = sw_prev; rec_tid[1::2] = sw_next; rec_ts[0::2] = sw_ts; rec_ts[1::2] = sw_ts
    rec_kind[0::2] = 0; rec_kind[1::2] = 1; rec_pay[0::2] = sw_st; rec_pay[1::2] = 0
    keep = rec_tid != 0
