    for si, r in enumerate(res):
        for tid_, (ts_, vt, vp, cm) in r['ctx'].items():
            if tid_ not in ctx or (ts_, si) < ctx[tid_][:2]:
                ctx[tid_] = (ts_, si, vt, vp, cm)
    # dict INSERTION ORDER = first-seen order of the merged stream, as in the sequential parser: ksched_split maps (vpid, vtid) ->
    # host tid by iterating ctx and lets a later entry win on a clash ("ambiguous" threads), so the order is part of the result
    ctx = {k: v[2:] for k, v in sorted(ctx.items(), key=lambda kv: kv[1][:2])}
    wk = (ld('wk_ts'), ld('wk_waker'), ld('wk_wakee'))
